seek(initial);ready=true;updateBadges();world?.setSpeed(speed);$('speedText').textContent=speed+'×';setPlay(!userPaused&&!document.hidden);$('speed').setAttribute('aria-label','切换步速，当前 '+speed+' 倍');function paintLoadStatus(){if(!world?.getCardStatus||flat||!ready)return;const state=world.getCardStatus(cursor);$('retryArt').hidden=state.status!=='error';if(state.status==='error')$('travelState').textContent='原卡读取失败';else $('travelState').textContent=done?'抵达终点':playing?(world?.getState?.().suspended?'暂离，已停步':state.status!=='ready'?'正读取原卡':'正在前进'):'已停步'}
